package teaching

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"fmt"
	"strings"
)

// Teaching credentials are generated by RKA itself; they are never the user's
// RKA password. They are stored only in teaching_identities, encrypted with
// AES-256-GCM under the application secret key. The plaintext never leaves the
// server process and never appears in JSON, logs or backups.
const credentialPrefix = "v1:"

// credentialKey normalises the application secret into an AES key. The config
// guarantees 32 bytes, but accepting any length keeps the adapter usable when
// embedded in tests or alternate bootstraps.
func credentialKey(secret []byte) []byte {
	if len(secret) == 32 {
		return secret
	}
	sum := sha256.Sum256(secret)
	return sum[:]
}

// encryptCredential seals one teaching credential. The nonce is prepended to
// the ciphertext and the whole blob is base64url encoded so it fits a text
// column without escaping.
func encryptCredential(secret []byte, plaintext string) (string, error) {
	block, err := aes.NewCipher(credentialKey(secret))
	if err != nil {
		return "", fmt.Errorf("teaching credential cipher: %w", err)
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return "", fmt.Errorf("teaching credential gcm: %w", err)
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := rand.Read(nonce); err != nil {
		return "", fmt.Errorf("teaching credential nonce: %w", err)
	}
	sealed := gcm.Seal(nil, nonce, []byte(plaintext), nil)
	return credentialPrefix + base64.RawURLEncoding.EncodeToString(append(nonce, sealed...)), nil
}

// decryptCredential opens a stored teaching credential.
func decryptCredential(secret []byte, encoded string) (string, error) {
	if !strings.HasPrefix(encoded, credentialPrefix) {
		return "", errors.New("teaching credential has an unknown format")
	}
	raw, err := base64.RawURLEncoding.DecodeString(strings.TrimPrefix(encoded, credentialPrefix))
	if err != nil {
		return "", fmt.Errorf("teaching credential decode: %w", err)
	}
	block, err := aes.NewCipher(credentialKey(secret))
	if err != nil {
		return "", fmt.Errorf("teaching credential cipher: %w", err)
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return "", fmt.Errorf("teaching credential gcm: %w", err)
	}
	if len(raw) < gcm.NonceSize() {
		return "", errors.New("teaching credential is truncated")
	}
	nonce, ciphertext := raw[:gcm.NonceSize()], raw[gcm.NonceSize():]
	plaintext, err := gcm.Open(nil, nonce, ciphertext, nil)
	if err != nil {
		return "", errors.New("teaching credential cannot be decrypted with the current application key")
	}
	return string(plaintext), nil
}
